const dir=mkdtempSync(join(tmpdir(),'peopleflow-test-')),port=4317,origin=`http://127.0.0.1:${port}`,pw='Sandbox-test-Only-2026!';let child;
async function start(){child=spawn(process.execPath,['server.mjs'],{cwd:import.meta.dirname,env:{...process.env,PORT:String(port),DB_PATH:join(dir,'test.sqlite'),SEED_PASSWORD:pw},stdio:['ignore','pipe','pipe']});await new Promise((resolve,reject)=>{child.stdout.on('data',d=>{if(d.toString().includes('ready'))resolve()});child.stderr.on('data',d=>{if(d.toString().includes('Error'))reject(Error(d.toString()))});child.on('exit',c=>{if(c)reject(Error('Server exited '+c))});});}
async function stop(){await new Promise(resolve=>{child.on('exit',resolve);child.kill()})}
async function call(path,{method='GET',data,cookie,csrf,from=origin}={}){const r=await fetch(origin+'/api'+path,{method,headers:{'Content-Type':'application/json',Origin:from,...(cookie?{Cookie:cookie}:{}),...(csrf?{'X-CSRF-Token':csrf}:{})},...(data===undefined?{}:{body:JSON.stringify(data)})});return {status:r.status,body:await r.json(),cookie:r.headers.get('set-cookie')}}
async function login(email){const r=await call('/login',{method:'POST',data:{email,password:pw}});assert.equal(r.status,200);const cookie=r.cookie.split(';')[0];const m=await call('/me',{cookie});return {cookie,csrf:m.body.csrf}}
before(start);after(async()=>{await stop();rmSync(dir,{recursive:true,force:true})});
test('authentication, cookies, invalid password and CSRF',async()=>{assert.equal((await call('/records/employees')).status,401);assert.equal((await call('/login',{method:'POST',data:{email:'admin@north.test',password:'wrong'}})).status,401);const a=await login('admin@north.test');assert.equal((await call('/records/employees',{method:'POST',cookie:a.cookie,data:{}})).status,403);assert.equal((await call('/records/employees',{...a,method:'POST',data:{},from:'https://evil.test'})).status,403);});
test('tenant isolation, owner scope, role restrictions, escaping data and validation',async()=>{const a=await login('admin@north.test'),b=await login('admin@south.test'),e=await login('employee@north.test');const list=await call('/records/employees',a);assert.equal(list.body.length,6);assert.equal((await call('/records/employees',e)).body.length,1);assert.equal((await call('/records/employees',{...b,method:'PATCH',data:{},...{},})).status,404);const id=list.body[0].id;assert.equal((await call('/records/employees/'+id,{...b,method:'PATCH',data:{}})).status,404);assert.equal((await call('/records/employees',{...e,method:'POST',data:{}})).status,403);assert.equal((await call('/records/candidates',e)).status,403);assert.equal((await call('/users',e)).status,403);assert.equal((await call('/tenants',a)).status,403);assert.equal((await call('/records/employees',{...a,method:'POST',data:{name:'bad'}})).status,400);const x=await call('/records/employees',{...a,method:'POST',data:{name:'<img src=x onerror=alert(1)>',email:'qa@example.test',department:'QA',title:'Tester',salary:12000,status:'Active',start:'2026-01-01',tenant:'south'}});assert.equal(x.status,201);assert.ok(!(await call('/records/employees',b)).body.some(r=>r.id===x.body.id));});
test('leave request, overlap, self-review denial and approval transition',async()=>{const e=await login('employee@north.test'),a=await login('admin@north.test');const data={type:'Annual',start:'2027-02-10',end:'2027-02-12',reason:'Sandbox'};const r=await call('/records/leave',{...e,method:'POST',data});assert.equal(r.status,201);assert.equal((await call('/records/leave',{...e,method:'POST',data})).status,409);assert.equal((await call('/records/leave/'+r.body.id,{...e,method:'PATCH',data:{status:'Approved'}})).status,403);assert.equal((await call('/records/leave/'+r.body.id,{...a,method:'PATCH',data:{status:'Approved'}})).status,200);assert.equal((await call('/records/leave/'+r.body.id,{...a,method:'PATCH',data:{status:'Rejected'}})).status,409);const own=await call('/records/leave',{...a,method:'POST',data:{...data,start:'2027-03-01',end:'2027-03-02'}});assert.equal((await call('/records/leave/'+own.body.id,{...a,method:'PATCH',data:{status:'Approved'}})).status,403);});
test('attendance enforces one session and clock sequence',async()=>{const e=await login('employee@north.test');assert.equal((await call('/attendance',{...e,method:'POST',data:{action:'out'}})).status,409);assert.equal((await call('/attendance',{...e,method:'POST',data:{action:'in'}})).status,200);assert.equal((await call('/attendance',{...e,method:'POST',data:{action:'in'}})).status,409);assert.equal((await call('/attendance',{...e,method:'POST',data:{action:'out'}})).status,200);assert.equal((await call('/attendance',{...e,method:'POST',data:{action:'out'}})).status,409);});
test('upload restrictions, cross-tenant downloads and audit',async()=>{const a=await login('admin@north.test'),b=await login('admin@south.test'),e=await login('employee@north.test');for(const name of ['evil.html','../escape.txt','script.js'])assert.equal((await call('/documents',{...a,method:'POST',data:{name,content:Buffer.from('hello').toString('base64')}})).status,400);assert.equal((await call('/documents',{...a,method:'POST',data:{name:'fake.pdf',content:Buffer.from('not pdf').toString('base64')}})).status,400);assert.equal((await call('/documents',{...e,method:'POST',data:{}})).status,403);const up=await call('/documents',{...a,method:'POST',data:{name:'policy.txt',content:Buffer.from('Sandbox policy').toString('base64')}});assert.equal(up.status,201);assert.equal((await fetch(origin+'/api/files/'+up.body.id,{headers:{Cookie:b.cookie}})).status,404);const own=await fetch(origin+'/api/files/'+up.body.id,{headers:{Cookie:e.cookie}});assert.equal(own.status,200);assert.match(own.headers.get('content-disposition'),/attachment/);assert.equal(await own.text(),'Sandbox policy');assert.ok((await call('/audit',a)).body.some(r=>r.action==='create:documents'));});
test('payroll drafts, platform isolation, suspension, logout and restart persistence',async()=>{const a=await login('admin@north.test'),p=await login('platform@peopleflow.test');assert.equal((await call('/records/employees',p)).status,403);const pay=await call('/records/payroll',{...a,method:'POST',data:{month:'2027-01'}});assert.equal(pay.status,201);assert.equal((await call('/records/payroll',{...a,method:'POST',data:{month:'2027-01'}})).status,409);assert.equal((await call('/tenants',{...p,method:'PATCH',data:{id:'south',plan:'Starter',status:'suspended'}})).status,200);const bs=await call('/login',{method:'POST',data:{email:'admin@south.test',password:pw}});assert.equal((await call('/me',{cookie:bs.cookie.split(';')[0]})).status,403);await stop();await start();assert.ok((await call('/records/payroll',a)).body.some(r=>r.id===pay.body.id));await call('/logout',{...a,method:'POST',data:{}});assert.equal((await call('/me',a)).status,401);});
test('shared task services enforce assignment, ownership, comments and version conflicts',async()=>{
 const a=await login('admin@north.test'),e=await login('employee@north.test'),hr=await login('hr@north.test');
 const data={title:'Review onboarding',description:'Fictional checklist',assignee:'north-employee',due:'2027-01-15',priority:'High'};
 assert.equal((await call('/tasks',{...e,method:'POST',data})).status,403);
 assert.equal((await call('/tasks',{...a,method:'POST',data:{...data,assignee:'south-employee'}})).status,400);
 const created=await call('/tasks',{...a,method:'POST',data});assert.equal(created.status,201);const id=created.body.id;
 assert.ok((await call('/tasks',e)).body.some(r=>r.id===id));
 assert.equal((await call('/tasks',{...e,method:'PATCH',data:{action:'assign',input:{id,assignee:'north-hr',version:1}}})).status,403);
 const status=await call('/tasks',{...e,method:'PATCH',data:{action:'status',input:{id,status:'In progress',version:1}}});assert.equal(status.status,200);
 assert.equal((await call('/tasks',{...e,method:'PATCH',data:{action:'status',input:{id,status:'Done',version:1}}})).status,409);
 const comment=await call('/tasks',{...e,method:'PATCH',data:{action:'comment',input:{id,text:'Checklist reviewed',version:2}}});assert.equal(comment.body.data.comments[0].text,'Checklist reviewed');
 assert.equal((await call('/tasks',{...hr,method:'PATCH',data:{action:'assign',input:{id,assignee:'north-hr',version:3}}})).status,200);
 assert.ok(!(await call('/tasks',e)).body.some(r=>r.id===id));
 assert.equal((await call('/tasks',{...e,method:'PATCH',data:{action:'status',input:{id,status:'Done',version:4}}})).status,404);
});
test('leave policy calendar, reservations, cancellation, tenant isolation and persistence',async()=>{
 const a=await login('admin@north.test'),e=await login('employee@north.test'),hr=await login('hr@north.test');
 const policy={type:'Personal',year:2028,allowance:3,workdays:[1,2,3,4,5],holidays:['2028-01-03']};
 assert.equal((await call('/leave-policies',{...e,method:'POST',data:policy})).status,403);
 assert.equal((await call('/leave-policies',{...hr,method:'POST',data:policy})).status,403);
 assert.equal((await call('/leave-policies',{...a,method:'POST',data:{...policy,holidays:['2028-02-30']}})).status,400);
 assert.equal((await call('/leave-policies',{...a,method:'POST',data:policy})).status,200);
 const r=await call('/records/leave',{...e,method:'POST',data:{type:'Personal',start:'2028-01-01',end:'2028-01-05',reason:'Sandbox calendar'}});assert.equal(r.status,201);
 const balance=async()=> (await call('/leave-summary?year=2028',e)).body.balances.find(x=>x.type==='Personal');
 assert.equal((await balance()).pending,2);assert.equal((await balance()).available,1);
 assert.equal((await call('/records/leave',{...e,method:'POST',data:{type:'Personal',start:'2028-01-06',end:'2028-01-07',reason:'Too many'}})).status,409);
 assert.equal((await call('/leave-policies',{...a,method:'POST',data:{...policy,workdays:[1,2,3,4,5,6]}})).status,409);
 assert.equal((await call('/leave-policies',{...a,method:'POST',data:{...policy,allowance:1}})).status,409);
 assert.equal((await call('/records/leave/'+r.body.id,{...hr,method:'PATCH',data:{status:'Cancelled'}})).status,200);
 assert.equal((await balance()).available,3);
 const own=await call('/records/leave',{...e,method:'POST',data:{type:'Personal',start:'2028-01-06',end:'2028-01-07',reason:'Own cancellation'}});
 assert.equal((await call('/records/leave/'+own.body.id,{...e,method:'PATCH',data:{status:'Cancelled'}})).status,200);
 assert.equal((await call('/records/leave/'+own.body.id,{...e,method:'PATCH',data:{status:'Cancelled'}})).status,403);
 await stop();await start();assert.equal((await balance()).allowance,3);assert.equal((await balance()).available,3);
});
