 assert.equal(service.calendar(e,'2072-02-01','2072-03-01').length,1);assert.equal(service.calendar(e,'2073-02-01','2073-03-01').length,0);assert.equal(service.calendar(e,'2076-02-01','2076-03-01').length,1);
 service.save(a,'holidays',{...holiday,name:'Half overlap',halfDay:true});assert.equal(service.holidayFraction(e,'2072-02-29',e.id),1);
 assert.throws(()=>service.list({...e,customRole:{},permissions:[]},'holidays'),/permission/i);
 assert.throws(()=>service.save({...a,role:'hr',customRole:{},permissions:['timeoff:read']},'holidays',holiday),/permission/i);
